shellCommands.command:
/bin/bash -lc "node --input-type=module - <<'EOF'
for (const path of ['/', '/product/classic-sneakers', '/product/missing']) {
  const response = await fetch("'`http://localhost:3000${path}`)
  const html = await response.text()
  console.log(path, {
    status: response.status,
    productCards: (html.match(/class="product-card"/g) || []).length,
    hero: html.includes('"'class=\"product-hero\"'),
    skeleton: html.includes('skeleton-text'),
    transitionType: html.includes('transitionTypes'),
    title: (html.match(/<title>(.*?)<\\/title>/) || [])[1],
  })
}
EOF"
